// HasRunsWith applies the HasEdge predicate on the "runs" edge with a given conditions (other predicates).
func HasRunsWith(preds ...predicate.BenchmarkRun) predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(func(s *sql.Selector) {
		step := newRunsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// HasPublicSnapshots applies the HasEdge predicate on the "public_snapshots" edge.
func HasPublicSnapshots() predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, false, PublicSnapshotsTable, PublicSnapshotsColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasPublicSnapshotsWith applies the HasEdge predicate on the "public_snapshots" edge with a given conditions (other predicates).
func HasPublicSnapshotsWith(preds ...predicate.BenchmarkPublicSnapshot) predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(func(s *sql.Selector) {
		step := newPublicSnapshotsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.BenchmarkProfile) predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.BenchmarkProfile) predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.BenchmarkProfile) predicate.BenchmarkProfile {
	return predicate.BenchmarkProfile(sql.NotPredicates(p))
}
